INSERT INTO "albums" VALUES(333,'原乡','罗大佑','中国','台湾','Synthpop',NULL,'《原乡》是罗大佑于1991年9月26日发行的专辑，共收录12首作品，融合电子合成、民谣与华语流行元素，展现其对故乡、社会与人文的深刻关怀。专辑中与周华健、李宗盛、赵传等人合作，呈现九十年代台湾音乐的多元面貌。',0,'2025-08-18',2,'大右音乐事业有限公司','covers/333-罗大佑-原乡.jpg','37:56',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1991','Pop',NULL,255,169,2,NULL,NULL,NULL);
