INSERT INTO "albums" VALUES(335,'演义','唐朝','中国','大陆','Heavy Metal, Progressive Metal, Folk Metal',NULL,'唐朝乐队1999年发行的第二张录音室专辑，融合重金属、前卫金属与中国传统元素，展现宏大叙事与文化意象。',0,'2025-07-27',1,'京文唱片','covers/335-唐朝-演义.jpg','62:52',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1999','Metal,Rock',NULL,185,171,20,NULL,NULL,NULL);
INSERT INTO "albums" VALUES(336,'Carsick Cars','Carsick Cars','中国','大陆','Noise Rock, Indie Rock, Post-Punk, Noise Pop, Jangle Pop',NULL,'Carsick Cars 的首张专辑融合了中国地下摇滚与 Sonic Youth 式的噪音美学，是北京独立音乐场景的重要标志之一。',0,'2025-07-28',4,'兵马司唱片','covers/336-Carsick_Cars-Carsick_Cars.jpg','53:59',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2007','Rock','Michael Pettis',34,172,1,NULL,NULL,NULL);
INSERT INTO "albums" VALUES(337,'神经','达明一派','中国','香港','Art Pop, Synthpop, Ambient Pop, Sophisti-Pop, Indie Pop',3.67,'《神经》是达明一派于1990年发行的专辑，融合电子流行、氛围流行与爵士元素，以粤语呈现都市感与政治讽刺，被视为香港艺术流行的代表作之一。',0,'2025-07-29',1,'宝丽金唱片','covers/337-达明一派-神经.jpg','2:58',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1990','Pop,Electronic',NULL,281,173,39,NULL,NULL,NULL);
INSERT INTO "albums" VALUES(338,'你来自何方','许景淳','中国','台湾','Baroque Pop, Sophisti-Pop, Adult Contemporary, Chamber Pop',3.5,'《你来自何方》是许景淳于1992年发行的概念专辑，融合古典流行与室内编制，展现女性内心的孤独与诗意，被誉为华语流行音乐中极具美学深度的作品。',0,'2025-07-30',1,'滚石唱片','covers/338-许景淳-你来自何方.jpg','47:22',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1992','Pop','',272,174,2,NULL,NULL,NULL);
