INSERT INTO "albums" VALUES(392,'Pluto','郑宜农','中国','台湾','Pop',3.3,'《Pluto》展现了郑宜农优秀的谱曲能力，吸收不同曲风并结合创作好手，歌词直白却纯粹，展现真我面向。',0,'2025-11-25',2,'Fire On Music Co., Ltd.','covers/392-郑宜农-Pluto.jpg','45:43',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2017','Pop',NULL,285,147,2,NULL,NULL,NULL);
INSERT INTO "albums" VALUES(393,'趣味小常识','九维','中国','大陆','Boom Bap, Hardcore Hip Hop',3.72,'《趣味小常识》是一张融合暴力、讽刺、都市批判与幽默的中文说唱专辑。九维以老北京痞气形象和犀利歌词刻画社会现实，既有早期直白粗粝的作品如《完犊子》《我想要》《冒着泡泡》，也有更抽象与深刻的主题如《枷锁-解锁》《权衡中》。专辑节奏简洁有力，采样与氛围感突出，展现了九维作为新一代北京地下嘻哈代表的才华。',0,'2025-11-25',1,'Undaloop唱片','covers/393-九维-趣味小常识.jpg','41:10',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020','Hip Hop',NULL,166,214,27,NULL,NULL,NULL);
INSERT INTO "albums" VALUES(394,'Diaries','Chestnut Bakery','中国','大陆','Shoegaze, Dream Pop',3.57,'《Diaries》是Chestnut Bakery于2015年发行的首张全长专辑，融合了Shoegaze、Dream Pop与Indie Rock等元素。专辑以温暖、忧郁、氛围感十足的音色为特色，女声空灵而富有感情，旋律常伴随失真吉他与缓慢鼓点，营造出冬日般的内省氛围。代表曲目包括《Train》《Moon Palace》，展现了史诗般的音墙与情感张力。整体风格既有抒情的独立流行气质，也带有慢核的沉静与梦幻色彩。',0,'2025-11-25',5,'Boring唱片','covers/394-Chestnut_Bakery-Diaries.jpg','49:39',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2015','Rock,Pop',NULL,35,215,17,NULL,NULL,NULL);
INSERT INTO "albums" VALUES(395,'时间的歌','陈绮贞','中国','台湾','Indie Pop, Singer-Songwriter, Chamber Pop',3.01,'《时间的歌》是陈绮贞于2013年发行的专辑，延续其独立流行与创作歌手的风格。作品以温柔、抒情的旋律和细腻的歌词著称，融合室内流行的编曲质感，展现了她独特的音乐美学。专辑整体氛围安静而富有诗意，体现了陈绮贞在创作上的成熟与内省。',0,'2013-12-06',2,'索尼音乐','covers/395-陈绮贞-时间的歌.jpg','46:08',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2013','Pop',NULL,298,216,2,NULL,NULL,NULL);
INSERT INTO "albums" VALUES(396,'吉他手','陈绮贞','中国','台湾','Pop Rock, Singer-Songwriter',3.65,'《吉他手》是陈绮贞于2002年发行的代表作之一，融合了流行摇滚与独立流行、民谣流行等元素，带有梦幻与迷幻色彩。专辑氛围柔和、抒情，歌词常涉及孤独、怀旧、爱情与自我反思，展现了她独特的创作美学。作品既有轻快的旋律如《小步舞曲》，也有更具另类摇滚质感的曲目，整体风格在华语流行与独立音乐之间取得平衡。',0,'2012-01-25',1,'魔岩唱片','covers/396-陈绮贞-吉他手.jpg','47:12',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2002','Rock,Pop,Folk','林暐哲',298,19,43,NULL,NULL,NULL);
INSERT INTO "albums" VALUES(397,'枯萎颂','王忆灵','中国','大陆','Chamber Folk, Singer-Songwriter, Art Pop',3.72,'《枯萎颂》是王忆灵于2024年发行的专辑，融合室内民谣、艺术流行与前卫摇滚元素。专辑以钢琴与管弦乐为主线，搭配诗意歌词与多样化编曲，展现出丰富的情感层次。作品既有温柔抒情的旋律，也包含实验性的结构与跨风格的探索，整体氛围唯美而内省。',0,'2025-11-25',3,'Not On Label','covers/397-王忆灵-枯萎颂.jpg','56:03',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2024','Folk,Pop,Rock','王忆灵',245,217,44,NULL,NULL,NULL);
INSERT INTO "albums" VALUES(398,'Reckoning','R.E.M.','美国','乔治亚州','Jangle Pop, New Wave, Post-Punk, Paisley Underground',3.81,'《Reckoning》是R.E.M.于1984年发行的第二张录音室专辑，延续了首张专辑《Murmur》的清新与神秘氛围，但整体更为明快、直接。专辑包含经典曲目《So. Central Rain》《(Don’t Go Back To) Rockville》《Pretty Persuasion》等，展现了乐队早期标志性的吉他叮咚声与Michael Stipe独特的诗意歌词。该作被视为R.E.M.早期最具代表性的作品之一，奠定了他们在独立摇滚与主流摇滚之间的独特地位。',0,'2011-11-25',1,'I.R.S.唱片','covers/398-R.E.M.-Reckoning.jpg','37:27',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1984','Rock,Pop,Punk','Don Dixon, Mitch Easter',121,218,42,NULL,NULL,NULL);
INSERT INTO "albums" VALUES(399,'Arntor','Windir','挪威','维斯特兰','Melodic Black Metal, Viking Metal, Folk Metal',3.8,'Windir的第二张专辑，以史诗般的旋律和挪威民间传说为主题，融合了黑金属与民谣元素，展现出冷冽、神话与胜利的氛围。',0,'2025-12-01',1,'Head Not Found唱片','covers/399-Windir-Arntor.jpg','46:12',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1999','Metal,Folk','Valfar',1,219,45,NULL,NULL,NULL);
INSERT INTO "albums" VALUES(400,'Instrumentals','Adrianne Lenker','美国','印第安纳波利斯','Ambient, Contemporary Folk, Ambient Americana',3.57,'Adrianne Lenker在森林小屋即兴录制的双曲专辑，包含《Songs for Indigo》和《Mostly Chimes》，以吉他与自然雨声、风铃声营造出宁静、冥想与温暖的氛围。',0,'2025-12-01',1,'4AD','covers/400-Adrianne_Lenker-Instrumentals.jpg','37:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020','Folk,Pop','Adrianne Lenker,Philip Weinrobe',4,220,18,NULL,NULL,NULL);
INSERT INTO "albums" VALUES(401,'Magical Mystery Tour','The Beatles','英国','利物浦','Psychedelic Pop, Pop Rock, Television Music',4.07,'《Magical Mystery Tour》是披头士于1967年11月27日发行的专辑，最初作为同名电视电影的原声带，后在美国以LP形式发行并加入单曲《Strawberry Fields Forever》《Penny Lane》《All You Need Is Love》等，逐渐被纳入官方唱片目录。专辑融合了幻想、迷幻与流行元素，包含《I Am the Walrus》《The Fool on the Hill》等经典曲目。',0,'2019-12-08',1,'Capitol唱片','covers/401-The_Beatles-Magical_Mystery_Tour.jpg','36:32',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1967','Rock,Pop','George Martin',137,221,17,NULL,NULL,NULL);
INSERT INTO "albums" VALUES(402,'Low','David Bowie','英国','伦敦','Art Rock',4.13,'《Low》是大卫·鲍伊于1977年1月14日发行的录音室专辑，由Tony Visconti制作，Brian Eno深度参与。专辑分为两部分：A面以碎片化的先锋流行与摇滚歌曲为主，如《Sound and Vision》《Be My Wife》，B面则是氛围化的电子器乐作品，如《Warszawa》《Subterraneans》。该作标志着鲍伊音乐风格的重大转折，融合了摇滚与电子实验，被视为“柏林三部曲”的开端，对后世的后朋克与电子音乐影响深远。',0,'2025-12-08',2,'RCA唱片','covers/402-David_Bowie-Low.jpg','39:03',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1977','Rock,Pop','Tony Visconti',43,112,17,NULL,NULL,NULL);
INSERT INTO "albums" VALUES(403,'Meat Is Murder','The Smiths','英国','曼彻斯特','Jangle Pop, Indie Pop',3.77,'《Meat Is Murder》是The Smiths于1985年2月11日发行的第二张录音室专辑，由Morrissey和Johnny Marr共同创作，Stephen Street担任工程师。专辑延续了乐队的独立摇滚风格，同时在歌词中加入了更强烈的政治与社会批判，如同名曲《Meat Is Murder》探讨素食主义与动物权益。其他代表曲目包括《The Headmaster Ritual》《I Want the One I Can’t Have》《That Joke Isn’t Funny Anymore》。该作在英国专辑榜上获得第一名，巩固了乐队在独立音乐界的地位。',0,'2025-12-08',3,'Rough Trade唱片','covers/403-The_Smiths-Meat_Is_Murder.jpg','39:41',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1985','Rock,Pop','The Smiths',145,161,17,NULL,NULL,NULL);
INSERT INTO "albums" VALUES(404,'I’m OK','陶喆','中国','台湾','Pop, Contemporary R&B',3.52,'《I’m OK》是陶喆于1999年6月9日发行的第二张录音室专辑，由他本人担任制作。专辑延续了首张专辑的R&B与流行摇滚融合风格，代表曲目包括《找自己》《普通朋友》《I’m OK》等。该作在华语乐坛引起广泛关注，确立了陶喆作为R&B与流行跨界代表人物的地位。',0,'2025-12-08',1,'滚石唱片','covers/404-陶喆-I’m_OK.jpg','51:02',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1999','Pop,R&B','陶喆',299,222,25,NULL,NULL,NULL);
