INSERT INTO "albums_2025" VALUES(336,'Carsick Cars','Carsick Cars','中国','大陆','Noise Rock, Indie Rock, Post-Punk, Noise Pop, Jangle Pop',NULL,'Carsick Cars 的首张专辑融合了中国地下摇滚与 Sonic Youth 式的噪音美学，是北京独立音乐场景的重要标志之一。',0,'2025-07-28',4,'兵马司唱片','covers/336-Carsick_Cars-Carsick_Cars.jpg','53:08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2007','Rock','Michael Pettis');
